EDU_DATA["zhsz-03-03-单选题-职业道德-40题"]={"meta":{"id":"zhsz-03-03-单选题-职业道德-40题","sub":"zhsz","subName":"综合素质","title":"03-单选-职业道德","kind":"single","count":40,"suggestMin":45,"doc":"01-综合素质-笔试/题库/03-单选题-职业道德（40题）.md","lectures":[{"url":"docs/01-综合素质-笔试/03-教师职业道德规范.md","title":"职业道德讲义"}]},"q":[{"n":1,"stem":"《中小学教师职业道德规范》共六条，贯穿其中的核心和灵魂是（ ）。（单选）","opts":[["A","严谨治学"],["B","爱与责任"],["C","终身学习"],["D","团结协作"]],"ans":"B","sol":"六条规范为爱国守法、爱岗敬业、关爱学生、教书育人、为人师表、终身学习，其核心和灵魂是爱与责任：爱体现为对学生的关爱、对事业的热爱，责任体现为教书育人的使命担当。A、D 是旧版规范中的条目；C 只是六条之一，不能概括全部。"},{"n":2,"stem":"某教师在课堂上多次发表否定党的领导、歪曲历史的言论。该教师主要违背了（ ）。（单选）","opts":[["A","爱岗敬业"],["B","关爱学生"],["C","终身学习"],["D","爱国守法"]],"ans":"D","sol":"爱国守法要求教师热爱祖国、热爱人民，拥护中国共产党领导，拥护社会主义，全面贯彻国家教育方针，自觉遵守教育法律法规，不得有违背党和国家方针政策的言行。题干中的言论直接违反这一条。A、B、C 与该行为的性质不对应。"},{"n":3,"stem":"某教师长期照搬多年前的旧教案，上课随意，作业批改只写一个\"阅\"字。该教师的行为主要违背了（ ）。（单选）","opts":[["A","爱岗敬业"],["B","关爱学生"],["C","为人师表"],["D","爱国守法"]],"ans":"A","sol":"爱岗敬业要求教师忠诚于人民教育事业，勤恳敬业，对工作高度负责，认真备课上课，认真批改作业，认真辅导学生，不得敷衍塞责。题干中\"照搬旧教案、随意上课、批改敷衍\"是典型的敷衍塞责。B、C 指向对待学生与自身示范，D 指向守法，均不如 A 贴切。"},{"n":4,"stem":"某教师对家庭条件差、成绩落后的学生很少提问，也很少批改其作业。该行为违背了关爱学生中（ ）的要求。（单选）","opts":[["A","保护学生安全"],["B","维护学生权益"],["C","关心爱护全体学生，平等公正对待学生"],["D","促进学生全面发展"]],"ans":"C","sol":"关爱学生要求教师关心爱护全体学生，尊重学生人格，平等公正对待学生，不歧视学生。题干中教师以家庭条件和成绩为由区别对待，正是\"没有做到面向全体、平等公正\"。A、B、D 虽也属关爱学生的内涵，但与题干所指的\"区别对待\"不对应。"},{"n":5,"stem":"某班主任评价学生时只看期末考试成绩，并据此分配班级各项荣誉。该做法违背了（ ）。（单选）","opts":[["A","教书育人"],["B","爱岗敬业"],["C","终身学习"],["D","爱国守法"]],"ans":"A","sol":"教书育人要求教师遵循教育规律，实施素质教育，循循善诱，诲人不倦，因材施教，培养学生良好品行，激发学生创新精神，促进学生全面发展，不以分数作为评价学生的唯一标准。题干中\"唯分数评价\"直接违反该条。B、C、D 与该评价行为的对应性不强。"},{"n":6,"stem":"某教师利用周末在自己家中为班上学生有偿补课，并向家长推荐自编教辅资料收取费用。该行为主要违背了（ ）。（单选）","opts":[["A","爱岗敬业"],["B","为人师表"],["C","教书育人"],["D","关爱学生"]],"ans":"B","sol":"为人师表要求教师作风正派，廉洁奉公，自觉抵制有偿家教，不利用职务之便谋取私利。有偿补课与推销教辅均属利用职务便利牟利，违反该条。A、C、D 虽在广义上也可能受影响，但题干行为性质是\"廉洁从教\"问题，对应 B 最准确。"},{"n":7,"stem":"某教师认为\"教了二十年，教材没大变，不需要再学习\"。这一认识违背了（ ）。（单选）","opts":[["A","爱国守法"],["B","爱岗敬业"],["C","终身学习"],["D","教书育人"]],"ans":"C","sol":"终身学习要求教师崇尚科学精神，树立终身学习理念，拓宽知识视野，更新知识结构，潜心钻研业务，勇于探索创新，不断提高专业素养和教育教学水平。学情与知识都在变化，\"不需要再学习\"直接违背该条。A、B、D 与\"拒绝学习\"这一核心不对应。"},{"n":8,"stem":"《新时代中小学教师职业行为十项准则》中排在首位的是（ ）。（单选）","opts":[["A","关心爱护学生"],["B","规范从教行为"],["C","坚持言行雅正"],["D","坚定政治方向"]],"ans":"D","sol":"十项准则的首条是\"坚定政治方向\"，要求教师坚持以习近平新时代中国特色社会主义思想为指导，拥护中国共产党的领导，贯彻党的教育方针，不得在教育教学活动中及其他场合有损害党中央权威、违背党的路线方针政策的言行。A、B、C 虽都在十项准则中，但均非首条。"},{"n":9,"stem":"某教师将班级学生名单提供给校外培训机构，并按推荐人数收取\"介绍费\"。该行为违反的准则主要是（ ）。（单选）","opts":[["A","传播优秀文化"],["B","加强安全防范"],["C","规范从教行为"],["D","秉持公平诚信"]],"ans":"C","sol":"规范从教行为要求教师勤勉敬业，乐于奉献，自觉抵制不良风气，不得组织、参与有偿补课，或为校外培训机构和他人介绍生源、提供相关信息。题干中提供名单并收取介绍费正属此列。A、B、D 与该行为的构成要件均不对应。"},{"n":10,"stem":"某教师在评选\"三好学生\"时，把自己亲戚的孩子列入名单，且不公开评选过程。该行为违反的准则主要是（ ）。（单选）","opts":[["A","秉持公平诚信"],["B","坚持言行雅正"],["C","潜心教书育人"],["D","自觉爱国守法"]],"ans":"A","sol":"秉持公平诚信要求教师在招生、考试、推优、保送及绩效考核、岗位聘用、职称评聘、评优评奖等工作中坚持原则、公平公正，不得徇私舞弊、弄虚作假。题干中在评优中照顾亲属、程序不公开，正违反该条。B、C、D 与\"评优不公\"不对应。"},{"n":11,"stem":"某教师收受家长赠送的购物卡，并在调换座位时给予该生照顾。该行为违反的准则主要是（ ）。（单选）","opts":[["A","关心爱护学生"],["B","加强安全防范"],["C","传播优秀文化"],["D","坚守廉洁自律"]],"ans":"D","sol":"坚守廉洁自律要求教师严于律己，清廉从教，不得索要、收受学生及家长财物，或参加由学生及家长付费的宴请、旅游、娱乐休闲等活动，不得利用家长资源谋取私利。收卡并为该生调座位，正是以权谋私。A、B、C 与\"收受财物\"这一核心事实无关。"},{"n":12,"stem":"某教师经常在课后单独约学生到偏僻场所，并言语挑逗，学生感到恐惧。该行为违反的准则主要是（ ）。（单选）","opts":[["A","秉持公平诚信"],["B","坚持言行雅正"],["C","规范从教行为"],["D","潜心教书育人"]],"ans":"B","sol":"坚持言行雅正要求教师为人师表，以身作则，举止文明，作风正派，自重自爱，不得与学生发生任何不正当关系，严禁任何形式的猥亵、性骚扰行为。题干中的挑逗言行已触及底线，须依法依规严肃处理。A、C、D 与该行为的性质不匹配。"},{"n":13,"stem":"地震警报响起时，某教师未组织学生疏散，独自先行离开教室。该行为违反的准则主要是（ ）。（单选）","opts":[["A","加强安全防范"],["B","爱岗敬业"],["C","传播优秀文化"],["D","秉持公平诚信"]],"ans":"A","sol":"加强安全防范要求教师增强安全意识，加强安全教育，保护学生安全，防范事故风险；不得在教育教学活动中遇突发事件、面临危险时，不顾学生安危擅离职守。题干中教师擅自先撤，正是\"不顾学生安危、擅离职守\"。B 过于笼统，C、D 完全无关。"},{"n":14,"stem":"某教师在课堂上多次宣扬封建迷信，贬损中华优秀传统文化，还向学生传播境外不良读物。该行为违反的准则主要是（ ）。（单选）","opts":[["A","关心爱护学生"],["B","潜心教书育人"],["C","规范从教行为"],["D","传播优秀文化"]],"ans":"D","sol":"传播优秀文化要求教师带头践行社会主义核心价值观，弘扬真善美，传递正能量，不得通过课堂、论坛、讲座、信息网络及其他渠道发表、转发错误观点，或编造散布虚假信息、不良信息。宣扬迷信、贬损传统文化、传播不良读物均违反该条。"},{"n":15,"stem":"某教师在工作时间长期经营网店，耽误备课上课，并利用课堂时间处理订单。该行为违反的准则主要是（ ）。（单选）","opts":[["A","坚守廉洁自律"],["B","潜心教书育人"],["C","坚持言行雅正"],["D","自觉爱国守法"]],"ans":"B","sol":"潜心教书育人要求教师落实立德树人根本任务，遵循教育规律和学生成长规律，因材施教，教学相长；不得违反教学纪律，敷衍教学，或擅自从事影响教育教学本职工作的兼职兼薪行为。工作时段经营网店正属\"影响本职工作的兼职\"。"},{"n":16,"stem":"某教师因学生口吃，在课堂上模仿其说话方式取笑。该行为违反的准则主要是（ ）。（单选）","opts":[["A","关心爱护学生"],["B","秉持公平诚信"],["C","加强安全防范"],["D","传播优秀文化"]],"ans":"A","sol":"关心爱护学生要求教师严慈相济，诲人不倦，真心关爱学生，严格要求学生，做学生良师益友；不得歧视、侮辱学生，严禁虐待、伤害学生。公开模仿取笑口吃学生，属于侮辱学生人格尊严，伤害学生心理。B、C、D 与这一行为不对应。"},{"n":17,"stem":"某教师在网上发布不实信息，诋毁本地教育政策并煽动家长聚集。该行为违反的准则主要是（ ）。（单选）","opts":[["A","坚守廉洁自律"],["B","潜心教书育人"],["C","自觉爱国守法"],["D","坚持言行雅正"]],"ans":"C","sol":"自觉爱国守法要求教师忠于祖国、忠于人民，恪守宪法原则，遵守法律法规，依法履行教师职责，不得损害国家利益、社会公共利益，或违背社会公序良俗。编造散布不实信息、煽动聚集已越出合法表达边界。A、B、D 与该行为性质不符。"},{"n":18,"stem":"教师职业道德区别于其他职业道德的显著标志是（ ）。（单选）","opts":[["A","鲜明的专业性"],["B","严格的组织性"],["C","强烈的纪律性"],["D","为人师表，以身作则"]],"ans":"D","sol":"教师劳动具有强烈的示范性，学生具有向师性，教师的一言一行都会成为学生模仿的对象，因此\"为人师表、以身作则\"成为教师职业道德区别于其他职业道德的显著标志。A、B、C 是许多职业共有的特征，不具区分度。"},{"n":19,"stem":"某教师坚持每天写反思日记，检视自己当天的言行是否伤害过学生。这体现的师德修养方法是（ ）。（单选）","opts":[["A","拜师学习"],["B","参加培训"],["C","自我反思，内省慎独"],["D","榜样示范"]],"ans":"C","sol":"师德修养强调\"内省\"\"慎独\"，即通过自我观察、自我评价、自我批评来提升道德境界，写反思日记正是自我反思的典型方式。A、B、D 属于外部学习途径，与题干\"检视自己言行\"的内在省察路径不同。"},{"n":20,"stem":"教师违反职业道德，情节严重、影响恶劣的，可能受到的处理是（ ）。（单选）","opts":[["A","仅进行批评教育"],["B","开除处分，并依法撤销其教师资格"],["C","调离原工作岗位即可"],["D","由其自行辞职了事"]],"ans":"B","sol":"依据《中小学教师违反职业道德行为处理办法》，对教师的处理包括警告、记过、降低岗位等级或撤职、开除；符合《教师资格条例》第十九条情形的，还应依法撤销其教师资格。A 处分畸轻；C、D 不是法定处理种类，不能替代纪律处分与资格处理。"},{"n":21,"stem":"某班主任规定：\"班干部只能由成绩前十名的学生担任，其他同学只需管好自己的学习。\"这一做法（ ）。（单选）","opts":[["A","有利于树立学习榜样"],["B","违背了关爱学生中平等公正对待学生的要求，也不利于全体学生的发展"],["C","符合班干部选拔的通常做法"],["D","有利于快速提高班级平均分"]],"ans":"B","sol":"关爱学生要求平等公正对待学生，班干部岗位是锻炼学生组织能力、责任意识的重要平台，以成绩为唯一门槛剥夺了多数学生的发展机会，也强化了\"唯分数\"导向。A、C、D 只从管理效率或分数角度辩护，忽视了教育公平与学生发展。"},{"n":22,"stem":"班上学生丢了手表，教师当场要求所有学生翻口袋、搜书包，并说\"谁拿了谁就是小偷\"。该教师的做法（ ）。（单选）","opts":[["A","有利于尽快找回失物"],["B","属于合理的班级管理措施"],["C","未违反师德，只是方法欠妥"],["D","侵犯了学生的人格尊严和隐私权，违背关爱学生的要求"]],"ans":"D","sol":"教师无权搜查学生身体和私人物品，公开指认\"小偷\"更是在全体学生面前给学生贴标签，侵犯人格尊严与隐私权。正确做法是了解情况、保护现场、必要时通知家长或报请学校依法处理。A、B、C 都在为侵权行为开脱。"},{"n":23,"stem":"开学初，一位家长为了让教师多照顾孩子，送来一张购物卡。教师最恰当的处理方式是（ ）。（单选）","opts":[["A","婉言拒绝，并向家长说明学校规定和教师应尽的职责"],["B","收下后在其他方面给予补偿"],["C","收下但不上报"],["D","转交给同事代为处理"]],"ans":"A","sol":"坚守廉洁自律要求教师不得收受学生及家长财物，遇到送礼应明确拒绝并说明教师会平等关爱每一名学生，以此打消家长顾虑。B、C 均构成收受财物，B 的\"补偿\"反而破坏公平；D 属于转移而不是拒绝，同样不合规。"},{"n":24,"stem":"某教师班上一名家长提出\"每月付2000元，请老师晚上给孩子补课\"，教师答应了。该教师的行为（ ）。（单选）","opts":[["A","属于双方自愿的劳务行为"],["B","只要不影响正常教学即可"],["C","违反规范从教行为的要求，属于有偿补课，应予禁止"],["D","只要不开发票就不算违规"]],"ans":"C","sol":"十项准则明确要求教师不得组织、参与有偿补课，或为校外培训机构和他人介绍生源、提供相关信息。对本班学生有偿补课还会造成\"课上不讲课后讲\"的利益冲突，损害教育公平。A、B、D 均以\"自愿\"\"不影响教学\"\"不开票\"为由规避禁令，不成立。"},{"n":25,"stem":"两位教师因班级评比产生矛盾，其中一位在家长群里公开贬低另一位教师。这种行为（ ）。（单选）","opts":[["A","违背了为人师表中尊重同事、团结协作的要求"],["B","属于个人言论自由"],["C","有利于家长了解班级情况"],["D","不影响学生，可以接受"]],"ans":"A","sol":"为人师表要求教师关心集体，团结协作，尊重同事，尊重家长。在家长群公开贬低同事，既损害教师群体形象，也会让家长和学生对教师失去信任。B 混淆了言论自由与职业规范；C、D 低估了该行为对学生和家校关系的负面影响。"},{"n":26,"stem":"某教师经常在课堂上向学生抱怨学校管理混乱、同事水平低。该行为（ ）。（单选）","opts":[["A","有助于培养学生的批判性思维"],["B","违背了为人师表、以身作则的要求"],["C","属于正当的情绪宣泄"],["D","不涉及师德问题"]],"ans":"B","sol":"教师的言行具有示范性，在学生面前贬损学校与同事，会削弱学生对学校规范与教师群体的认同，也传递了消极的处事方式，违背为人师表、以身作则的要求。A 把牢骚误当批判性思维培养；C、D 否认了该行为的职业影响。"},{"n":27,"stem":"春游途中突降暴雨、河水上涨，某教师为赶行程仍坚持带学生过河。该行为（ ）。（单选）","opts":[["A","体现了高度的责任心"],["B","属于勇敢果断的表现"],["C","违背了加强安全防范的要求，把学生置于危险之中"],["D","只要没有发生事故就没有问题"]],"ans":"C","sol":"加强安全防范要求教师增强安全意识、保护学生安全、防范事故风险。明知风险仍带队过河，是把行程置于学生生命安全之上，属重大失职。A、B 把冒险误作负责；D 以结果论安全，违背\"生命至上、预防为先\"的基本要求。"},{"n":28,"stem":"某教师为完成\"家访率100%\"的考核指标，在未实际家访的情况下补填了家访记录。该行为（ ）。（单选）","opts":[["A","只是工作方法灵活"],["B","属于形式主义，不涉及师德问题"],["C","可以提高工作效率"],["D","违背了秉持公平诚信的要求，属于弄虚作假"]],"ans":"D","sol":"秉持公平诚信要求教师坚持原则、诚实守信，不得弄虚作假。伪造家访记录既欺瞒学校考核，也剥夺了家长真实沟通的机会，属典型的弄虚作假。A、C 以\"效率\"\"灵活\"美化造假；B 忽视了诚信是师德的基本要求。"},{"n":29,"stem":"某学生因父母离异情绪低落、成绩下滑，教师不仅在班里说\"你爸妈不要你了\"，还把其家庭情况当作谈资讲给同事听。该行为（ ）。（单选）","opts":[["A","有利于引起家长重视"],["B","属于正常的教师之间交流"],["C","侵犯学生隐私、伤害学生情感，违背关爱学生的要求"],["D","只是言语不当，口头道歉即可"]],"ans":"C","sol":"关爱学生要求尊重学生人格、保护学生隐私。离异家庭情况属于学生敏感信息，教师当众议论并外传，会造成二次伤害，损害学生尊严与信任。A、B 忽视了隐私保护义务；D 低估了行为性质，仅有道歉不足以弥补。"},{"n":30,"stem":"家长对教师的教学方法有异议，并在班级群里公开指责。教师最恰当的做法是（ ）。（单选）","opts":[["A","私下沟通，耐心解释教学设计的依据，并虚心听取家长意见"],["B","在群里逐条反驳，要求家长公开道歉"],["C","对该生降低关注以示惩戒"],["D","直接申请调换班级"]],"ans":"A","sol":"为人师表要求尊重家长，教师应通过平等、理性的沟通化解分歧，说明教学设计的依据，同时吸纳合理建议，形成家校合力。B 会把分歧扩大为对抗；C 将矛盾转嫁给学生，属报复性做法；D 回避问题，均不妥当。"},{"n":31,"stem":"某教师因早上与家人争吵，上课时对一名小声说话的学生罚站一节课，而对其他说话的学生未作处理。该行为（ ）。（单选）","opts":[["A","属于正常的纪律管理"],["B","只要罚站时间不长就合规"],["C","符合教育惩戒的适当性原则"],["D","属于因个人情绪、好恶选择性实施教育惩戒，为规则所禁止"]],"ans":"D","sol":"《中小学教育惩戒规则（试行）》明确禁止因个人情绪、好恶实施或者选择性实施教育惩戒，也禁止超过正常限度的罚站。该教师把私人情绪带入课堂，且同类行为区别对待，既违规又失公信。A、B、C 均以\"纪律管理\"\"时间不长\"掩盖违规实质。"},{"n":32,"stem":"某教师让未完成作业的学生在操场跑十圈，其中一名学生因此晕倒。该行为（ ）。（单选）","opts":[["A","属于常规的体育锻炼"],["B","属于变相体罚，违背关爱学生要求，学校应承担相应责任"],["C","有利于培养学生的意志品质"],["D","只要学生自愿就没有问题"]],"ans":"B","sol":"超出正常限度、强制做不适动作或高强度运动属于变相体罚，法律与师德规范均明确禁止；学生因此受伤，学校应依法承担相应责任。A 混淆了体育锻炼与惩罚；C 以\"锻炼意志\"为体罚辩护；D 忽视了学生的身心承受能力与教师的主导责任。"},{"n":33,"stem":"某教师要求全班统一购买自己编写的练习册，并将其作为家庭作业的唯一来源。该行为（ ）。（单选）","opts":[["A","违反坚守廉洁自律的要求，属于向学生推销教辅材料谋取私利"],["B","有利于保证作业质量"],["C","属于正常的教学安排"],["D","只要家长同意即可"]],"ans":"A","sol":"坚守廉洁自律要求教师不得向学生推销图书报刊、教辅材料、社会保险或利用家长资源谋取私利。教师自编材料统一售卖并绑定作业，存在明显的利益冲突，也加重学生负担。B、C、D 均以\"质量\"\"安排\"\"同意\"为由掩盖牟利实质。"},{"n":34,"stem":"某教师常用\"你们这届是我带过最差的一届\"\"你们脑子进水了吗\"等话语批评学生。该行为（ ）。（单选）","opts":[["A","属于严格要求"],["B","有助于激发学生斗志"],["C","只是口头禅，无伤大雅"],["D","使用侮辱性语言，违背关爱学生与坚持言行雅正的要求"]],"ans":"D","sol":"关爱学生要求不侮辱学生、不伤害学生，坚持言行雅正要求教师语言规范、举止文明。此类贬损性话语会打击学生自尊与学习信心，属语言暴力。A 把侮辱当严格；B 属错误的\"激将法\"观念；C 低估了语言伤害的持续性。"},{"n":35,"stem":"学校推荐一名教师参加市级培训，该教师以\"培训耽误我上课\"为由拒绝，也不愿参加校本教研。该教师（ ）。（单选）","opts":[["A","忠于职守，值得肯定"],["B","违背了终身学习的要求，不利于专业发展"],["C","有自主选择权，无可厚非"],["D","只要教学成绩好就不必培训"]],"ans":"B","sol":"终身学习要求教师树立终身学习理念，拓宽知识视野，更新知识结构，不断提高专业素养和教育教学水平；参加进修培训既是权利也是义务。A 把拒绝学习当作敬业；C 忽视了教师专业发展的强制性要求；D 以成绩替代专业成长。"},{"n":36,"stem":"某教师发现班上有学生被家长长期殴打，于是私下\"教育\"家长，并威胁\"再打就让学生退学\"。该教师的做法（ ）。（单选）","opts":[["A","出发点可以理解，但方式不当，应依法报告并推动有关部门介入"],["B","完全正确，体现了对学生的保护"],["C","属于越权行为，应当不予理会"],["D","只要家长改正就无需处理"]],"ans":"A","sol":"教师发现学生遭受侵害负有强制报告义务，应及时向公安、民政、教育等部门报告，由有关部门依法处置；以\"劝退\"威胁家长既不合法，也会使受害学生失去保护。B 忽视了法定程序；C 放弃保护职责；D 把判断权交给施暴方。"},{"n":37,"stem":"科任教师发现学生有辍学倾向，未告知班主任，也未与家长联系，认为\"这不是我的事\"。该教师的做法（ ）。（单选）","opts":[["A","职责清晰，无可指摘"],["B","属于合理分工"],["C","违背了教书育人、关爱学生的要求，未履行保护学生受教育权的职责"],["D","应当表扬其不越权"]],"ans":"C","sol":"教师法定义务包括关心爱护全体学生、制止有害于学生的行为，控辍保学是全体教师的共同责任。发现问题不报告、不沟通，实质是放任学生失学。A、B、D 以\"分工\"\"不越权\"为失职辩护，均不成立。"},{"n":38,"stem":"某教师在班会课上向学生宣扬\"读书无用，赚钱才是硬道理\"，并称\"爱国是空洞的口号\"。该行为（ ）。（单选）","opts":[["A","属于个人价值观，与学生无关"],["B","有利于学生了解社会现实"],["C","属于言论自由范畴"],["D","违背了坚定政治方向、传播优秀文化的要求"]],"ans":"D","sol":"坚定政治方向要求教师贯彻党的教育方针，不得在教育教学活动中及其他场合有损害党中央权威、违背党的路线方针政策的言行；传播优秀文化要求弘扬真善美、传递正能量。课堂传播\"读书无用\"\"爱国空洞\"，与立德树人根本任务背离。"},{"n":39,"stem":"某教师得知一名学生家长是当地企业家后，安排该生担任班长，并在各项评优中优先考虑。该行为（ ）。（单选）","opts":[["A","有利于争取家长对学校工作的支持"],["B","属于正常的家校关系维护"],["C","违背了公平公正对待学生的要求，损害教育公平"],["D","只要该生能力达到标准就没有问题"]],"ans":"C","sol":"关爱学生要求平等公正对待学生，秉持公平诚信要求在评优评奖中坚持原则、公平公正。以家庭背景作为任用与评优依据，会使教育资源向优势家庭倾斜，损害其他学生的平等机会。A、B 混淆了家校合作与利益输送；D 回避了程序不公。"},{"n":40,"stem":"某教师未经家长同意，把学生的家庭情况、成绩排名发到班级群里\"督促家长重视\"。该行为（ ）。（单选）","opts":[["A","有利于家校共育"],["B","侵犯学生及家庭隐私，违背关爱学生、尊重家长的要求"],["C","属于正常的信息公开"],["D","只要不写学生姓名就合规"]],"ans":"B","sol":"学生的成绩、家庭情况属于个人信息与隐私，公开传播会造成标签化与家长间攀比，甚至引发歧视，违反关爱学生与尊重家长的要求，也违反个人信息保护的相关规定。A、C 以\"共育\"\"公开\"为侵权辩护；D 在班群里即便隐去姓名，也往往可被识别。"}]};
